def js(obj):
    return json.dumps(obj, ensure_ascii=False, indent=2)

def line_of(texts, key):
    """first line carrying id="<base id>" in app.html, else in the js file.
    Dynamic ids such as d1jWz' + kind + ' are matched on their literal prefix."""
    base = key.split('.')[0]
    pat = re.compile(r'id="' + re.escape(base) + r'"')
    for name, t in texts:
        m = pat.search(t)
        if m:
            return t.count('\n', 0, m.start()) + 1, ('' if name == 'app.html' else name)
    stem = re.sub(r'(phone|email)$', '', base)
    if stem != base:
        pat2 = re.compile(r"id=\"" + re.escape(stem) + r"' \+ kind")
        for name, t in texts:
            m = pat2.search(t)
            if m:
                return t.count('\n', 0, m.start()) + 1, ('' if name == 'app.html' else name)
    return 0, ''

def with_lines(tbl, texts, missing):
    out = {}
    for k, v in tbl.items():
        ln, f = line_of(texts, k)
        if not ln: missing.append(k)
        out[k] = [v[0], v[1], ln, f]
    return out

def strip(html):
    i, j = html.find(BEGIN), html.find(END)
    if i < 0 or j < 0: return html, False
    j += len(END)
    if html[j:j+1] == '\n': j += 1
    return html[:i] + html[j:], True

def block(b, texts, stamp):
    css = io.open(os.path.join(HERE, 'badge.css'), encoding='utf-8').read().rstrip('\n')
    rt = io.open(os.path.join(HERE, 'badge-runtime.js'), encoding='utf-8').read().rstrip('\n')
    missing = []
    L0 = with_lines(b['l0'], texts, missing)
    L1 = with_lines(b['l1'], texts, missing)
    L2 = with_lines(b['l2'], texts, missing)
    rt = (rt.replace('__KEY__', b['key']).replace('__SEC__', js(b['sec']))
            .replace('__L0__', js(L0)).replace('__L1__', js(L1)).replace('__L2__', js(L2))
            .replace('__L1SEL__', b['l1sel']).replace('__L2SEL__', b['l2sel'])
            .replace('__VARIANT__', js(b['variant'])).replace('__PUSH__', js(b['push']))
            .replace('__HOME__', js(b['home'])).replace('__BUILD__', stamp))
    out = (BEGIN + '\n<style id="debugBadge">\n' + css + '\n</style>\n'
           '<script id="debugBadge">\n' + rt + '\n</script>\n' + END + '\n')
    return out, missing

# ── index.html: three removable pieces, each wrapped in BADGE-INDEX markers ──
INDEX_CSS = """  /* Debug badge toggle (MB). Whole block removable. */
  .dbg-toggle {
    display: flex; align-items: center; gap: 8px;
    margin-top: auto; padding: 14px 28px;
    border-top: 1px solid rgba(255,255,255,0.08);
    font-size: 12px; color: rgba(255,255,255,0.55);
    cursor: pointer; user-select: none;
  }
  .dbg-toggle:hover { color: rgba(255,255,255,0.85); }
  .dbg-toggle input { accent-color: #7fe3c7; margin: 0; }
  .dbg-toggle span { flex: 1; }
  .dbg-toggle em {
    font-style: normal; font-family: ui-monospace, Menlo, monospace; font-size: 10px;
    border: 1px solid rgba(255,255,255,0.22); border-radius: 3px; padding: 1px 4px;
    color: rgba(255,255,255,0.45);
  }
"""
INDEX_HTML = """  <!-- Debug badge toggle (MB). Whole block removable; the launcher works without it.
       See V2/badge/README.md -->
  <label class="dbg-toggle" id="dbgToggle">
    <input type="checkbox" id="dbgChk">
    <span>Debug badge</span>
    <em>D</em>
  </label>
"""
INDEX_JS = """  /* Debug badge toggle (MB). Whole block removable.
     The checkbox and a D in the parent window both postMessage app.html; app.html
     also listens for D and the triple-tap itself, so either side can toggle.
     Re-pushed on iframe load so a reload keeps the badge. */
  (function () {
    var chk = document.getElementById('dbgChk');
    if (!chk) return;
    function push() {
      try { frame.contentWindow.postMessage({ cloakedDebug: chk.checked }, '*'); } catch (e) {}
    }
    chk.addEventListener('change', push);
    frame.addEventListener('load', push);
    window.addEventListener('message', function (e) {
      if (e.data && e.data.cloakedDebugState !== undefined) chk.checked = !!e.data.cloakedDebugState;
    });
    document.addEventListener('keydown', function (e) {
      if (e.key !== 'd' && e.key !== 'D') return;
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      var t = e.target;
      if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
      chk.checked = !chk.checked; push();
    });
  })();
"""
PIECES = [
    ('/*BADGE-INDEX css BEGIN*/\n',  '/*BADGE-INDEX css END*/\n',  INDEX_CSS,  '</style>',  'before'),
    ('<!-- BADGE-INDEX html BEGIN -->\n', '<!-- BADGE-INDEX html END -->\n', INDEX_HTML, '</aside>', 'before'),
    ('/*BADGE-INDEX js BEGIN*/\n',   '/*BADGE-INDEX js END*/\n',   INDEX_JS,   '</script>', 'before-last'),
]
def index_strip(t):
    changed = False
    for a, b, _, _, _ in PIECES:
        i, j = t.find(a), t.find(b)
        if i >= 0 and j >= 0:
            t = t[:i] + t[j + len(b):]; changed = True
    return t, changed
def index_add(t):
    for a, b, body, anchor, where in PIECES:
        k = t.find(anchor) if where == 'before' else t.rfind(anchor)
        if k < 0: raise SystemExit('index.html: anchor %s not found' % anchor)
        t = t[:k] + a + body + b + t[k:]
    return t

def main():
    # deterministic stamp: a hash of the tables + runtime + css, so --check is
    # quiet when nothing changed and the panel still says which build it is
    src = io.open(__file__, encoding='utf-8').read() + io.open(os.path.join(HERE, 'badge-runtime.js'), encoding='utf-8').read() + io.open(os.path.join(HERE, 'badge.css'), encoding='utf-8').read()
    stamp = 'V2 badge ' + hashlib.sha256(src.encode('utf-8')).hexdigest()[:8]
    report = []
    for name, b in BUILDS.items():
        d = os.path.join(V2, name)
        ap = os.path.join(d, 'app.html')
        html = io.open(ap, encoding='utf-8').read()
        base, had = strip(html)
        if STRIP:
            new = base
        else:
            texts = []
            for s in b['src']:
                texts.append((s, base if s == 'app.html' else io.open(os.path.join(d, s), encoding='utf-8').read()))
            blk, missing = block(b, texts, stamp + ' · ' + name)
            k = base.rfind('</body>')
            new = base[:k] + blk + base[k:]
            if missing: report.append('  %s: no line found for %s' % (name, ', '.join(missing)))
        if new != html:
            report.append('  %s/app.html: %s' % (name, 'strip' if STRIP else ('rebuild' if had else 'add')))
            if not CHECK: io.open(ap, 'w', encoding='utf-8').write(new)
        ip = os.path.join(d, 'index.html')
        idx = io.open(ip, encoding='utf-8').read()
        ibase, ihad = index_strip(idx)
        inew = ibase if STRIP else index_add(ibase)
        if inew != idx:
            report.append('  %s/index.html: %s' % (name, 'strip' if STRIP else ('rebuild' if ihad else 'add')))
            if not CHECK: io.open(ip, 'w', encoding='utf-8').write(inew)
    print(('CHECK ONLY - would change:' if CHECK else 'changed:') + ('\n' + '\n'.join(report) if report else ' nothing'))
    if not STRIP:
        pend = sorted(set(k for b in BUILDS.values() for t in (b['l0'], b['l1'], b['l2'])
                          for k, v in t.items() if v[0].startswith('?')))
        print('codes pending (marked ?): %d keys' % len(pend))

if __name__ == '__main__':
    main()
